-- 디폴트 전시 삽입
INSERT INTO exhibitions (created_at, exhibitions_id, users_id, view_count, like_count, exhibitions_uuid, title, description, thumbnail_url) VALUES
                                                                                                                                                (NOW(), 1, 2, 203, 205, UNHEX(REPLACE('d8265394-573e-4d5e-baf0-8b75fe10896e', '-', '')), '겨울 풍경', '차가운 겨울의 아름다움을 담은 풍경과 장면들을 감상해보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/portrait/portrait2.jpg'),
                                                                                                                                                (NOW(), 2, 2, 152, 155, UNHEX(REPLACE('b35b9358-df1d-4d9c-b362-cb51e94e5e25', '-', '')), '겨울의 맛', '따뜻하고 매력적인 겨울의 음식을 담은 아름다운 사진들을 즐겨보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/food/food2.jpg'),
                                                                                                                                                (NOW(), 3, 3, 313, 216, UNHEX(REPLACE('5f2e2f9d-0411-437e-91e5-7922a35b1044', '-', '')), '가을의 정수', '가을의 생생한 색감과 텍스처를 담은 작품들을 감상해보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/art/art2.jpg'),
                                                                                                                                                (NOW(), 4, 2, 22, 12, UNHEX(REPLACE('d61d5f71-f5bc-4ab3-92c8-62b1de207102', '-', '')), '가을의 풍경', '평화롭고 그림 같은 가을 풍경을 담은 작품들을 감상해보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/landscape/landscape2.jpg'),
                                                                                                                                                (NOW(), 5, 2, 15, 10, UNHEX(REPLACE('74148b2b-9f0e-4650-8e94-3ec6ccde34a6', '-', '')), '봄의 시작', '봄의 신선함과 생동감을 담은 다채로운 이미지들을 즐겨보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/architecture/architecture2.jpg'),
                                                                                                                                                (NOW(), 6, 3, 1000, 562, UNHEX(REPLACE('f5f16b49-12ac-4745-aac5-4b1b269eabcb', '-', '')), '봄밤의 매력', '봄밤의 마법 같은 야경을 담은 작품들로 계절의 본질을 느껴보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/nightview/nightview2.jpg'),
                                                                                                                                                (NOW(), 7, 2, 123, 120, UNHEX(REPLACE('a3087e10-7da2-4760-a82d-d80c4397e0e1', '-', '')), '봄의 역동성', '봄의 활기와 에너지를 담은 다양한 활동과 장면들을 감상하세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/sports/sports2.jpg'),
                                                                                                                                                (NOW(), 8, 1, 456, 423, UNHEX(REPLACE('35519784-ce74-443b-8665-d1c00cafa6f5', '-', '')), '태양의 아름다움', '장관을 이루는 태양의 이미지들을 통해 황홀한 순간들을 감상해보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/journalism/journalism2.jpg'),
                                                                                                                                                (NOW(), 9, 2, 78, 55, UNHEX(REPLACE('31216ebf-27a5-4013-bedf-06642401f332', '-', '')), '구름의 예술', '다양한 형태와 색상의 구름을 담은 예술적인 사진들을 감상해보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/wildlife/wildlife2.jpg'),
                                                                                                                                                (NOW(), 10, 3, 41, 40, UNHEX(REPLACE('2c8221cf-ea0b-442e-a49e-cd02e4af3ca8', '-', '')), '바람의 속삭임', '바람이 불어오는 순간의 매력을 담은 작품들로 감성적인 경험을 해보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/nightview/nightview3.jpg'),
                                                                                                                                                (NOW(), 11, 3, 22, 20, UNHEX(REPLACE('93dbf19e-6d22-4e3d-8a3b-c04b233bea38', '-', '')), '불의 열정', '붉은 불꽃과 열정적인 순간들을 담은 작품들을 감상하세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/food/food3.jpg'),
                                                                                                                                                (NOW(), 12, 2, 123, 120, UNHEX(REPLACE('0e7cb02a-0750-4f4b-b3ad-bb1aaf5577bd', '-', '')), '꽃의 매력', '다양한 꽃의 아름다움과 생동감을 담은 사진들로 자연의 경이로움을 느껴보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/portrait/portrait2.jpg'),
                                                                                                                                                (NOW(), 13, 5, 6, 4, UNHEX(REPLACE('61110976-0977-4393-8234-1ed9fd510cf3', '-', '')), '말의 세계', '말의 우아함과 힘을 담은 이미지들로 이 멋진 동물을 감상하세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/landscape/landscape3.jpg'),
                                                                                                                                                (NOW(), 14, 2, 0, 0, UNHEX(REPLACE('7ea6b1a6-b6c0-4731-87e1-f4844cca01d3', '-', '')), '코의 신비', '코의 독특한 모양과 질감을 다룬 작품들로 신비로운 세계를 탐험해보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/art/art3.jpg'),
                                                                                                                                                (NOW(), 15, 4, 77, 50, UNHEX(REPLACE('6422e443-fedd-4f94-ae26-6e4fa9b58860', '-', '')), '입의 감정', '입의 형태와 감정을 표현한 작품들로 다양한 감정을 느껴보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/sports/sports3.jpg'),
                                                                                                                                                -- 아래부터는 사진도 들어가는 테스트 데이터 --
                                                                                                                                                (NOW(), 16, 1, 320, 300, UNHEX(REPLACE('e4f96b48-d5bf-4be3-bb3e-1d632acfc582', '-', '')), '초상화의 세계', '인간의 내면을 포착한 초상화들을 감상하며, 다양한 감정과 표정을 느껴보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/portrait/portrait1.jpg'),
                                                                                                                                                (NOW(), 17, 2, 210, 190, UNHEX(REPLACE('d87f6b84-a4d5-4157-9f40-9036679bd821', '-', '')), '아름다운 풍경', '자연과 도시 풍경의 조화로운 순간을 담은 작품으로, 평화롭고 장엄한 경치를 만끽하세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/landscape/landscape1.jpg'),
                                                                                                                                                (NOW(), 18, 3, 412, 398, UNHEX(REPLACE('92de6ba7-70bc-4f53-85fa-7a2c5ef712b1', '-', '')), '거리의 매력', '도시의 거리에서 발견할 수 있는 독특한 순간과 분위기를 담아낸 작품들을 감상하세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/street/street1.jpg'),
                                                                                                                                                (NOW(), 19, 2, 512, 500, UNHEX(REPLACE('66210cc6-92e7-471a-9b78-fef651e2b1d3', '-', '')), '음식의 예술', '미각을 자극하는 아름다운 음식 사진들로, 시각적 즐거움과 미각의 만남을 경험해 보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/food/food1.jpg'),
                                                                                                                                                (NOW(), 20, 3, 175, 150, UNHEX(REPLACE('76694b0e-0e61-46c6-a3a0-6f622c738c00', '-', '')), '고혹적인 미술의 세계', '풍부한 색감과 독창적인 형태로 감동을 주는 미술 작품을 만나보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/art/art1.jpg'),
                                                                                                                                                (NOW(), 21, 1, 420, 410, UNHEX(REPLACE('aebf6707-8fea-4d89-93ed-fec79d095722', '-', '')), '현대 건축', '최첨단 디자인과 기능성을 갖춘 현대 건축물의 매력을 담은 전시입니다.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/architecture/architecture1.jpg'),
                                                                                                                                                (NOW(), 22, 2, 90, 85, UNHEX(REPLACE('b5d60569-2253-49aa-aaea-39e1336e53e6', '-', '')), '야경의 매력', '화려한 도시 야경과 평화로운 자연 야경을 담은 사진으로 일상의 스트레스를 잊으세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/nightview/nightview1.jpg'),
                                                                                                                                                (NOW(), 23, 3, 134, 120, UNHEX(REPLACE('6bef0c47-623d-4e54-ba8c-efcc95605ce7', '-', '')), '스포츠의 순간', '역동적이고 힘찬 스포츠 활동의 순간들을 포착한 작품들로 에너지를 충전하세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/sports/sports1.jpg'),
                                                                                                                                                (NOW(), 24, 1, 67, 60, UNHEX(REPLACE('e049f2d8-fed9-408f-82bc-453cfdec2922', '-', '')), '저널리즘의 시선', '뉴스와 사회적 이슈를 담은 사진들로 세상의 다양한 이야기를 만나보세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/journalism/journalism1.jpg'),
                                                                                                                                                (NOW(), 25, 2, 92, 85, UNHEX(REPLACE('4a89d801-8d9e-4cdc-aac4-05e76e2deb5e', '-', '')), '야생의 세계', '자연의 원시적 아름다움과 야생동물의 생동감을 담은 사진들로 호기심을 자극하세요.', 'https://d1g6qszf7cmafu.cloudfront.net/exhibition/test/wildlife/wildlife1.jpg')
ON DUPLICATE KEY UPDATE exhibitions_id = exhibitions_id;


